public static TFMClassificationID classifyInput(str _input)
{
    TFMClassificationHierarchy  hierarchy;
    Common                      record;

    while select hierarchy where _input != ''
    {
        record = TFMClassificationHierarchy::findRecord(hierarchy.TableName, hierarchy.FieldName, _input);
        if(record != null)
        {
            return hierarchy.ClassificationID;
        }
    }
    return '';
}

public static Common findRecord(TableName _tableName, FieldName _fieldName, str _value)
{
    Query                   q       = new Query();
    QueryBuildDataSource    qbds    = q.addDataSource(tableName2Id(_tableName));
    QueryBuildRange         qbr     = qbds.addRange(fieldName2Id(tableName2Id(_tableName), _fieldName));
    QueryRun                qr;
    qbr.value(_value);

    qr = new QueryRun(q);

    //qr.run();
    if (qr.next())
    {
        return qr.get(tableName2Id(_tableName));
    }
    return null;
}

/// <summary>
/// Finds and replaces the input based on the FieldNameReturn and if the _returnNameClause has been set only if the _returnNameClause is the same. E.g. ItemId
/// </summary>
public static str findAndReplaceInput(str _input, str _returnNameClause = '')
{
    TFMClassificationHierarchy  hierarchy;
    Common                      record;
    SysDictTable                sdt;

    while select hierarchy where (hierarchy.FieldNameReturn == _returnNameClause || (hierarchy.FieldNameReturn && _returnNameClause)) && _input != ''
    {
        record = TFMClassificationHierarchy::findRecord(hierarchy.TableName, hierarchy.FieldName, _input);
        if(record != null)
        {
            sdt = new SysDictTable(record.TableId);

            return strFmt('%1',record.(sdt.fieldName2Id(hierarchy.FieldNameReturn)));
        }
    }
    return _input;
}

public static boolean exist(TFMClassificationID _classificationID)
{
    TFMClassificationHierarchy hierarchy;

    select firstonly RecId from hierarchy where hierarchy.ClassificationID == _classificationID;

    return hierarchy.RecId != 0;
}

public static void initializeStandard()
{
    TFMClassificationHierarchy  classHierarchy;
    TFMClassificationID         classificationID = 'Item Number';

    if(!TFMClassificationHierarchy::exist(classificationID))
    {
        classHierarchy.ClassificationID = classificationID;
        classHierarchy.TableName        = tableStr(InventTable);
        classHierarchy.FieldName        = fieldStr(InventTable, ItemId);
        classHierarchy.insert();
    }
    classificationID = 'License Plate';
    if(!TFMClassificationHierarchy::exist(classificationID))
    {
        classHierarchy.ClassificationID = classificationID;
        classHierarchy.TableName        = tableStr(WHSLicensePlate);
        classHierarchy.FieldName        = fieldStr(WHSLicensePlate, LicensePlateId);
        classHierarchy.insert();
    }

    classificationID = 'Serial Number';
    if(!TFMClassificationHierarchy::exist(classificationID))
    {
        classHierarchy.ClassificationID = classificationID;
        classHierarchy.TableName        = tableStr(InventSerial);
        classHierarchy.FieldName        = fieldStr(InventSerial, InventSerialId);
        classHierarchy.FieldNameReturn  = fieldStr(InventSerial, ItemId);
        classHierarchy.insert();
    }

    classificationID = 'Barcode';
    if(!TFMClassificationHierarchy::exist(classificationID))
    {
        classHierarchy.ClassificationID = classificationID;
        classHierarchy.TableName        = tableStr(InventItemBarcode);
        classHierarchy.FieldName        = fieldStr(InventItemBarcode, itemBarCode);
        classHierarchy.FieldNameReturn  = fieldStr(InventItemBarcode, ItemId);
        classHierarchy.insert();
    }

    classificationID = 'GTIN';
    if(!TFMClassificationHierarchy::exist(classificationID))
    {
        classHierarchy.ClassificationID = classificationID;
        classHierarchy.TableName        = tableStr(InventItemGTIN);
        classHierarchy.FieldName        = fieldStr(InventItemGTIN, GlobalTradeItemNumber);
        classHierarchy.FieldNameReturn  = fieldStr(InventItemBarcode, ItemId);
        classHierarchy.insert();
    }
}
